targets.rawSql:
SELECT toString(${group_by}) as grouping,
  ${main_panel_select}
FROM ${table}
WHERE $__timeFilter(timestamp)
  AND $__adHocFilter() 
  AND ${main_panel_filters}
GROUP BY min, grouping
ORDER BY grouping, min ASC
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=Main Panel; du=${__user.login}'

list.definition:
SELECT CASE
  WHEN '${main_panel_select:text}' = 'Page Views' THEN ${page_views_filter:sqlstring}
  WHEN '${main_panel_select:text}' = 'Visits' THEN ${visits_filter:sqlstring}
  WHEN '${main_panel_select:text}' = 'API Requests' THEN ${api_requests_filter:sqlstring}
  ELSE '1=1'
END

